import os
from typing import Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


class KMSDecryptionError(Exception):
    pass


def decrypt_ciphertext(
    ciphertext_blob: bytes,
    *,
    region_name: Optional[str] = None,
    encryption_context: Optional[dict[str, str]] = None,
) -> bytes:
    if not isinstance(ciphertext_blob, (bytes, bytearray)) or not ciphertext_blob:
        raise ValueError("ciphertext_blob must be non-empty bytes")

    kms = boto3.client(
        "kms",
        region_name=region_name or os.getenv("AWS_REGION") or os.getenv("AWS_DEFAULT_REGION"),
    )

    try:
        response = kms.decrypt(
            CiphertextBlob=bytes(ciphertext_blob),
            EncryptionContext=encryption_context or {},
        )
        plaintext = response["Plaintext"]
        if not isinstance(plaintext, (bytes, bytearray)):
            raise KMSDecryptionError("AWS KMS returned an invalid plaintext payload")
        return bytes(plaintext)
    except (ClientError, BotoCoreError) as e:
        raise KMSDecryptionError(f"AWS KMS decrypt failed: {e}") from e
